mapper.select:
SELECT * FROM t_proj_project_signed
WHERE deleted = false
    AND signed_stat_date >= #{startDate}
    AND signed_stat_date <= #{endDate}

SELECT * FROM t_proj_project_signed
WHERE deleted = false
    AND district_code = #{districtCode}
    AND signed_stat_date >= #{startDate}
    AND signed_stat_date <= #{endDate}

SELECT * FROM t_proj_project_signed
WHERE deleted = false
    AND zone_code = #{zoneCode}
    AND signed_stat_date >= #{startDate}
    AND signed_stat_date <= #{endDate}

SELECT district, district_code, COUNT(1) as proj_nums, ROUND(SUM(qyje), 2) as ztz FROM t_proj_project_signed WHERE deleted = false AND (progress > 0 OR (progress = 0 AND check_status = 1))
AND ((p_type = 1 AND invest_money >= 0.05 AND invest_money < 1) OR (p_type = 2 AND invest_money >= 50 AND invest_money < 1000))
AND ((p_type = 1 AND invest_money >= #{rmb}) OR (p_type = 2 AND invest_money >= #{dollar}))
AND signed_stat_date >= #{startDate}
AND signed_stat_date <= #{endDate}
GROUP BY district, district_code

SELECT z.dept_name as district, z.dept_code as district_code, COUNT(m.id) as proj_nums, ROUND(SUM(m.qyje), 2) as ztz FROM t_proj_project_signed m JOIN t_common_dept z ON m.zone_code = z.dept_code WHERE m.deleted = false AND z.deleted = false AND z.dept_code LIKE CONCAT(#{deptCode}, '%') AND (m.progress > 0 OR (m.progress = 0 AND m.check_status = 1)) and z.dept_type = 3 and z.dept_status = 1
AND ((m.p_type = 1 AND m.invest_money >= 0.05 AND m.invest_money < 1) OR (m.p_type = 2 AND m.invest_money >= 50 AND m.invest_money < 1000))
AND ((m.p_type = 1 AND m.invest_money >= #{rmb}) OR (m.p_type = 2 AND m.invest_money >= #{dollar}))
AND m.signed_stat_date >= #{startDate}
AND m.signed_stat_date <= #{endDate}
GROUP BY z.dept_name, z.dept_code

SELECT a.name AS name, a.invest_money AS investMoney, a.district AS district, a.zone_name AS zoneName, a.investor AS investor, a.desc AS projDesc, CASE WHEN (a.progress = 0 AND a.check_status = 1 OR a.progress = 0 AND a.check_status = 2 OR a.progress = 1 AND a.check_status = 3) THEN '已签约' WHEN (a.progress = 1 AND a.check_status = 1 OR a.progress = 1 AND a.check_status = 2 OR a.progress = 5 AND a.check_status = 3) THEN '已注册' WHEN (a.progress = 2 AND a.check_status = 1 OR a.progress = 2 AND a.check_status = 2 OR a.progress = 3 AND a.check_status = 3) THEN '已开工' WHEN (a.progress = 3 AND a.check_status = 1 OR a.progress = 3 AND a.check_status = 2) THEN '已竣工' WHEN (a.progress = 4 AND a.check_status = 1 OR a.progress = 4 AND a.check_status = 2 OR a.progress = 2 AND a.check_status = 3) THEN '已报批' WHEN (a.progress = 5 AND a.check_status = 1 OR a.progress = 5 AND a.check_status = 2 OR a.progress = 4 AND a.check_status = 3) THEN '已备案' ELSE NULL END AS progressRd FROM t_proj_project_signed a WHERE a.deleted = false AND (a.progress > 0 OR (a.progress = 0 AND a.check_status = 1))
AND a.signed_stat_date >= #{currStartDate}
AND a.signed_stat_date <= #{currEndDate}
AND a.proj_type LIKE CONCAT(#{projType}, '%')
AND ((a.p_type = 1 AND a.invest_money >= 0.05 AND a.invest_money < 1) OR (a.p_type = 2 AND a.invest_money >= 50 AND a.invest_money < 1000))
AND ((a.p_type = 1 AND a.invest_money >= #{rmb}) OR (a.p_type = 2 AND a.invest_money >= #{dollar}))

SELECT COUNT(1) as projNums, ROUND(SUM(qyje), 2) as ztz, LEFT(signed_stat_date, 7) as signedDate FROM t_proj_project_signed WHERE deleted = false AND (progress > 0 OR (progress = 0 AND check_status = 1))
AND signed_stat_date >= #{currStartDate}
AND signed_stat_date <= #{currEndDate}
AND zone_code LIKE CONCAT(#{districtCode}, '%')
GROUP BY LEFT(signed_stat_date, 7) ORDER BY LEFT(signed_stat_date, 7)

SELECT COUNT(b.id) as projNums, a._code as projType, a._name as projName FROM t_proj_type a LEFT JOIN ( SELECT id, proj_type FROM t_proj_project_signed WHERE deleted = false AND (progress > 0 OR (progress = 0 AND check_status = 1))
AND signed_stat_date >= #{currStartDate}
AND signed_stat_date <= #{currEndDate}
AND zone_code LIKE CONCAT(#{districtCode}, '%')
) b ON b.proj_type LIKE CONCAT(a._code, '%') WHERE a.deleted = false AND (a.p_id = '1' OR a._code = '2') GROUP BY a._code, a._name ORDER BY a._code
